const products=[{id:'rose-hair',name:'The Rose & Pearl Hairpiece',category:'accessories',label:'A LITTLE EVERYDAY BLOOM',image:'assets/flower-hair.jpg',alt:'Pink crochet roses with draped pearl strands, handmade by Sunita',description:'Pink crochet roses meet delicate pearl strands in this handmade hair accessory. Ask Sunita about colours and custom details for your occasion.'},{id:'festive-dress',name:'The Festive Crochet Ensemble',category:'festive',label:'FOR SPECIAL LITTLE MOMENTS',image:'assets/festive-dress.jpg',alt:'Pink handmade crochet festive clothing displayed on a Krishna figurine',description:'A festive crochet creation with floral details, as featured on Sunita’s Instagram. Confirm sizing, colours, and the pieces included directly with Sunita.'}];
const $=s=>document.querySelector(s);const config=window.SHOP_CONFIG||{};let basket=[];try{const saved=JSON.parse(localStorage.getItem('sunita-basket')||'[]');if(Array.isArray(saved))basket=saved.filter(x=>products.some(p=>p.id===x.id)&&Number.isInteger(x.qty)&&x.qty>0&&x.qty<=20).map(x=>({id:x.id,qty:x.qty,preference:String(x.preference||'').slice(0,500)}))}catch{}
function escapeHtml(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function renderProducts(filter='all'){const list=products.filter(p=>filter==='all'||p.category===filter);$('#products').innerHTML=list.map(p=>`<article class="product-card"><button class="product-image" data-product="${p.id}" aria-label="View ${p.name}"><img src="${p.image}" alt="${p.alt}" loading="lazy"><span class="product-tag">${p.label}</span></button><div class="product-meta"><div><h3>${p.name}</h3><p>Handmade · Ask for price</p></div><button class="add-button" data-product="${p.id}" aria-label="Choose ${p.name}">+</button></div></article>`).join('');$('#result-count').textContent=`${list.length} creation${list.length===1?'':'s'}`}
function save(){try{localStorage.setItem('sunita-basket',JSON.stringify(basket))}catch{}$('#bag-count').textContent=basket.reduce((n,x)=>n+x.qty,0)}
let toastTimer;function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3000)}
function showProduct(id){const p=products.find(x=>x.id===id);if(!p)return;$('#product-detail').innerHTML=`<img class="detail-photo" src="${p.image}" alt="${p.alt}"><p class="eyebrow">HANDMADE BY SUNITA</p><h2 id="product-title">${p.name}</h2><p>${p.description}</p><p class="muted">Price and availability confirmed on enquiry.</p><form id="add-form"><label for="preference">Your colour or custom preferences (optional)</label><input id="preference" maxlength="500" placeholder="e.g. Ivory roses for a wedding"><label for="quantity">Quantity</label><input id="quantity" type="number" value="1" min="1" max="20" required><button class="button" style="margin-top:20px;width:100%" type="submit">Add to my basket <span>+</span></button></form>`;$('#product-dialog').showModal();$('#add-form').addEventListener('submit',e=>{e.preventDefault();const qty=Number($('#quantity').value);if(!Number.isInteger(qty)||qty<1||qty>20)return;const preference=$('#preference').value.trim();const existing=basket.find(x=>x.id===id&&x.preference===preference);if(existing){if(existing.qty+qty>20){toast('Please keep each item to 20 pieces or fewer.');return}existing.qty+=qty}else basket.push({id,qty,preference});save();$('#product-dialog').close();toast('A little lovely added to your basket.');})}
function renderBasket(){save();$('#basket-items').innerHTML=basket.length?basket.map((x,i)=>{const p=products.find(p=>p.id===x.id);return `<div class="basket-row"><div><strong>${p.name}</strong><small>${escapeHtml(x.preference||'Design as pictured')}</small><button data-remove="${i}">Remove</button></div><div class="qty"><button data-change="${i}" data-delta="-1" aria-label="Decrease ${p.name} quantity">−</button><span>${x.qty}</span><button data-change="${i}" data-delta="1" aria-label="Increase ${p.name} quantity">+</button></div></div>`}).join(''):'<p>Your basket is waiting for a little handmade joy. <a class="text-link" href="#collection" id="browse-basket">Browse the collection ↗</a></p>';$('#order-form').hidden=!basket.length;const ready=/^\d{8,15}$/.test(config.whatsappNumber||'');$('#send-order').hidden=!ready;$('#connection-note').hidden=ready;$('#instagram-order').hidden=ready;}
function requestText(){return `Hi Sunita! I’m interested in your handmade crochet creations.\n\n${basket.map(x=>`${x.qty} × ${products.find(p=>p.id===x.id).name}${x.preference?'\nPreferences: '+x.preference:''}`).join('\n\n')}\n\n${$('#order-notes').value.trim()?'Additional details: '+$('#order-notes').value.trim()+'\n\n':''}Please let me know the price, availability, making time, and delivery options. Thank you!`}
document.addEventListener('click',e=>{const b=e.target.closest('button,a');if(!b)return;if(b.dataset.product)showProduct(b.dataset.product);if(b.dataset.close)$('#'+b.dataset.close).close();if(b.dataset.filter){document.querySelectorAll('[data-filter]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b))});renderProducts(b.dataset.filter)}if(b.dataset.remove!==undefined){basket.splice(Number(b.dataset.remove),1);renderBasket()}if(b.dataset.change!==undefined){const x=basket[Number(b.dataset.change)];x.qty=Math.min(20,x.qty+Number(b.dataset.delta));if(x.qty<=0)basket.splice(Number(b.dataset.change),1);renderBasket()}if(b.id==='browse-basket')$('#basket-dialog').close()});
$('#bag-button').addEventListener('click',()=>{renderBasket();$('#basket-dialog').showModal()});$('#custom-button').addEventListener('click',()=>{renderBasket();$('#order-form').hidden=false;$('#order-notes').value='I’d love a custom crochet creation. My idea is: ';$('#basket-dialog').showModal();$('#order-notes').focus()});$('#order-form').addEventListener('submit',e=>{e.preventDefault();if(!/^\d{8,15}$/.test(config.whatsappNumber||'')){toast('WhatsApp ordering is being set up. Copy your request instead.');return}window.open('https://wa.me/'+config.whatsappNumber+'?text='+encodeURIComponent(requestText()),'_blank','noopener,noreferrer')});$('#copy-order').addEventListener('click',async()=>{try{await navigator.clipboard.writeText(requestText());toast('Request copied. Share it with Sunita.')}catch{toast('Copying is unavailable here. Select and copy the request below.');let field=document.querySelector('#manual-copy');if(!field){field=document.createElement('textarea');field.id='manual-copy';field.setAttribute('aria-label','Your order request to copy');$('#order-form').append(field)}field.value=requestText();field.focus();field.select()}});document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}}));$('#year').textContent=new Date().getFullYear();renderProducts();save();
